1	/*!
2	 * \file tl/transform/lower_l2_persistent_annotation.cc
3	 * \brief Lower L2 persistent annotation
4	 */
5	
6	#include "support/check.h"
7	#include <tvm/ir/cast.h>
8	#include <tvm/tirx/analysis.h>
9	#include <tvm/tirx/builtin.h>
10	#include <tvm/tirx/stmt.h>
11	#include <tvm/tirx/stmt_functor.h>
12	#include <tvm/tirx/transform.h>
13	
14	#include "op/builtin.h"
15	
16	namespace tvm {
17	namespace tl {
18	
19	namespace attr {
20	// BlockAttr, Containing the layout for all the buffers in the block
21	constexpr const char *kL2RatioMap = "l2_hit_ratio_map";
22	constexpr const char *kL2PersistentMap = "l2_persistent_map";
23	} // namespace attr
24	
25	using namespace tirx;
26	using namespace ffi;
27	
28	class LowerL2Persistent : public StmtExprMutator {
29	public:
30	  static PrimFunc Substitute(PrimFunc &f) {
31	    PrimFuncNode *fptr = f.CopyOnWrite();
32	    LowerL2Persistent substituter;
33	    // Trace the buffer map for tvm_access_ptr
34	    substituter.buffer_map_.insert(f->buffer_map.begin(), f->buffer_map.end());
35	    for (const auto &[_, buffer] : f->buffer_map) {
36	      substituter.buffer_data_to_buffer_.Set(buffer->data, buffer);
37	    }
38	    fptr->body = substituter.VisitStmt(f->body);
39	    Map<String, Array<PrimExpr>> init_l2_persistent_map;
40	    for (auto [buffer, hit_ratio] : substituter.hit_ratio_map_) {
41	      Array<PrimExpr> l2_persistent_arguments;
42	      // Argument 0: hit ratio
43	      // Argument 1: size in bytes
44	      l2_persistent_arguments.push_back(hit_ratio);
45	      PrimExpr size_in_bytes = IntImm(DataType::Int(64), buffer->dtype.bytes());
46	      for (auto dim : buffer->shape) {
47	        size_in_bytes = size_in_bytes * dim;
48	      }
49	      l2_persistent_arguments.push_back(size_in_bytes);
50	      init_l2_persistent_map.Set(buffer->name, l2_persistent_arguments);
51	    }
52	    if (!init_l2_persistent_map.empty()) {
53	      f = WithAttr(std::move(f), attr::kL2PersistentMap,
54	                   init_l2_persistent_map);
55	    }
56	    return f;
57	  }
58	
59	  Stmt VisitStmt_(const SBlockNode *op) final {
60	    // Record the mapping from buffer data var to buffer for later lookup
61	    for (auto buffer : op->alloc_buffers) {
62	      buffer_map_.insert({buffer->data, buffer});
63	    }
64	    for (auto match_buffer : op->match_buffers) {
65	      buffer_map_.insert({match_buffer->buffer->data, match_buffer->buffer});
66	    }
67	    for (auto buffer : op->alloc_buffers) {
68	      buffer_data_to_buffer_.Set(buffer->data, buffer);
69	    }
70	
71	    if (op->annotations.count(attr::kL2RatioMap)) {
72	      auto hit_ratio_map = op->annotations.at(attr::kL2RatioMap)
73	                               .as<Map<Var, FloatImm>>()
74	                               .value();
75	      for (auto [buffer_var, hit_ratio] : hit_ratio_map) {
76	        Buffer buffer = buffer_data_to_buffer_.at(buffer_var);
77	        hit_ratio_map_.Set(buffer, hit_ratio);
78	      }
79	    }
80	    auto block = Downcast<SBlock>(StmtExprMutator::VisitStmt_(op));
81	    auto block_ptr = block.CopyOnWrite();
82	    block_ptr->annotations.erase(attr::kL2RatioMap);
83	    return block;
84	  }
85	
86	private:
87	  // Mapping from data Var of a Buffer to Buffer, for lookup
88	  Map<Var, Buffer> buffer_data_to_buffer_;
89	  std::unordered_map<Var, Buffer, ObjectPtrHash, ObjectPtrEqual> buffer_map_;
90	  Map<Buffer, FloatImm> hit_ratio_map_;
91	  LowerL2Persistent() = default;
92	};
93	
94	using namespace tirx::transform;
95	
96	tvm::transform::Pass LowerL2Persistent() {
97	  auto pass_func = [=](PrimFunc f, const IRModule &m, const PassContext &ctx) {
98	    return LowerL2Persistent::Substitute(f);
99	  };
100	  return CreatePrimFuncPass(pass_func, 0, "tl.LowerL2Persistent", {});
101	}
102	
103	TVM_FFI_STATIC_INIT_BLOCK() {
104	  namespace refl = reflection;
105	  refl::GlobalDef().def("tl.cuda.transform.LowerL2Persistent",
106	                        LowerL2Persistent);
107	}
108	
109	} // namespace tl
110	} // namespace tvm
